import { z } from 'zod';
import { ADMIN_ROLES } from '../enums.js';
import { text, phone, district, hasKeys, NO_FIELDS } from './common.js';

export const MAX_ADDRESSES = 5;

// A saved delivery address. `id` is generated by the backend, never by the client.
const addressFields = {
  label: text(1, 30),
  recipientName: text(2, 100),
  phone,
  line: text(10, 300),
  district,
};
export const addressInputSchema = z.strictObject({ ...addressFields, isDefault: z.boolean().default(false) });
export const addressPatchSchema = z.strictObject({ ...addressFields, isDefault: z.boolean() }).partial().refine(hasKeys, NO_FIELDS);
export const addressSchema = z.strictObject({ id: z.string().regex(/^[a-z0-9]{8,16}$/), ...addressFields, isDefault: z.boolean() });

export const customerSchema = z.strictObject({
  name: text(2, 100),
  phone,
  email: z.email().max(254).nullable().default(null),
  // Legacy single free-text address (Phase 2); saved addresses live in `addresses`.
  address: text(10, 300).nullable().default(null),
  addresses: z.array(addressSchema).max(MAX_ADDRESSES).default([]),
});

// What a customer may change about their own profile. Email comes from the verified token, never from the body.
export const customerProfilePatchSchema = z.strictObject({ name: text(2, 100), phone }).partial().refine(hasKeys, NO_FIELDS);

export const adminSchema = z.strictObject({
  name: text(2, 100),
  email: z.email().max(254),
  role: z.enum(ADMIN_ROLES),
  active: z.boolean().default(true),
});